<?php require 'config.php'; $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $hash=password_hash($_POST['password'],PASSWORD_DEFAULT); $s=$conn->prepare('INSERT INTO admins(name,email,password) VALUES(?,?,?)');$s->bind_param('sss',$_POST['name'],$_POST['email'],$hash);$msg=$s->execute()?'Admin created. Delete setup-admin.php now.':'Could not create admin (email may already exist).'; } ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Setup Admin</title><link rel="stylesheet" href="assets/css/style.css"></head><body><section class="section"><div class="container form" style="max-width:550px"><h1>Create PACPET Admin</h1><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><form method="post"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" required><br><button class="btn">Create Admin</button></form></div></section></body></html>
